import axios from 'axios'
import { MessageBox, Message } from 'element-ui'
import store from '@/store'
import { getToken } from '@/utils/auth'

// create an axios instance
const service = axios.create({
  baseURL: process.env.VUE_APP_PLA_API,
  // baseURL: 'http://192.168.110.25:18088/',
  
  // url = base url + request url
  // withCredentials: true, // send cookies when cross-domain requests
  timeout: 200000 // request timeout
})

// request interceptor
service.interceptors.request.use(
  config => {
    console.log('store.getters', store.getters)
    if (store.getters.plaToken) {
      config.headers['Authorization'] = 'Bearer ' + store.getters.plaToken
      // config.headers['TENANT-CODE'] = 'ASP0005'
    }
    return config
  },
  error => {
    // do something with request error
    console.log(error) // for debug
    return Promise.reject(error)
  }
)

// response interceptor
service.interceptors.response.use(
  /**
   * If you want to get http information such as headers or status
   * Please return  response => response
   */

  /**
   * Determine the request status by custom code
   * Here is just an example
   * You can also judge the status by HTTP Status Code
   */
  response => {
    const res = response.data
    if (res.msgCode === 110 || res.msgCode === 403 || res.msgCode === 404) {
      console.log('token已失效！！')
      this.$store.dispatch('user/logout')
      this.$router.push(`/login?redirect=${this.$route.fullPath}`)
    }
    if (response.status === 200 && !res.status) {
      return res
    }
    if (response.status === 200 && res.status === 'T') {
      // if (res.msg != null) {
      //   Message({
      //     message: res.msg,
      //     duration: 5 * 1000
      //   })
      // }
      return res.result
    }
    // if the custom code is not 20000, it is judged as an error.
    if (response.status === 200 && res.status === 'F') {
      // Message({
      //   message: res.msg || 'Error',
      //   type: 'error',
      //   duration: 2 * 1000
      // })
      // return res
      return Promise.reject(new Error(res.msg || 'Error'))
      // 50008: Illegal token; 50012: Other clients logged in; 50014: Token expired;
    } else {
      return res
    }
    // return Promise.reject(new Error(res.msg || 'Error'))
  },
  error => {
    console.log('err' + error) // for debug
    Message({
      message: error.message,
      type: 'error',
      duration: 5 * 1000
    })
    // if (error.response.status === 401) {
    //   location.reload()
    // }
    return Promise.reject(error)
  }
)

export default service
