// 获取患者信息
export function getPatientInfo(data) {
  return platformRequest({
    url: '/hsop/business/entrance/operateInfoJson',
    method: 'post',
    data: {
      params: {
        basic: {
          ...baseParams,
          transactionCode: "opt_0001"
        },
        detail: data
      },
    }
  })
}

