// 获取科室信息
export function getDepList(data) {
  // 选择院区之后进入科室选择  此处改变baseParams中的院区信息
  baseParams.branchCode = localStorage.getItem('branchCode') || '02'
  return platformRequest({
    url: '/hsop/business/entrance/operateInfoJson',
    method: 'post',
    data: {
      params: {
        basic: {
          ...baseParams,
          // transactionCode: "opt_0009"
          transactionCode: "opt_0005"
        },
        // detail: data
        detail: {...data, queryType: 3}
      }
    }
  })
}

