<template>
  <el-dialog
    title="AI分析结果"
    :visible.sync="dialogVisible"
    width="30%"
    :before-close="handleClose">
    <el-descriptions :column="1" border>
      <el-descriptions-item label="舌色">{{ aiReviewResult.舌色 }}</el-descriptions-item>
      <el-descriptions-item label="舌形">{{ aiReviewResult.舌形 }}</el-descriptions-item>
      <el-descriptions-item label="苔质">{{ aiReviewResult.苔质 }}</el-descriptions-item>
      <el-descriptions-item label="苔色">{{ aiReviewResult.苔色 }}</el-descriptions-item>
      <el-descriptions-item label="津液">{{ aiReviewResult.津液 }}</el-descriptions-item>
    </el-descriptions>
    <span slot="footer" class="dialog-footer">
      <el-button @click="dialogVisible = false">取 消</el-button>
      <el-button type="primary" @click="submitForm">上 传</el-button>
    </span>
  </el-dialog>
</template>

<script>
import {addTongueDiagnosisResult} from '@/service/shezhen'
export default {
  name: 'ShezhenAdminAiResult',

  data() {
    return {
      dialogVisible: false,
      aiReviewResult: {},
      aiResult: {}
    };
  },

  mounted() {
    
  },

  methods: {
    show(result, aiResult) {
      this.dialogVisible = true;
      this.aiReviewResult = result;
      this.aiResult = aiResult;
    },
    submitForm() {
      addTongueDiagnosisResult({
        ...this.aiResult,
        tongueId: this.aiResult.id,
        tongueColour: this.aiReviewResult.tongueColour,
        tongueShapes: this.aiReviewResult.tongueShapes,
        tongueFurqualitys: this.aiReviewResult.tongueFurqualitys,
        tonguefurColour: this.aiReviewResult.tonguefurColour,
        bodyFluid: this.aiReviewResult.bodyFluid,
        imgFlag: 0,
        createBy: 'AI'
      }).then(res => {
        this.$message.success('提交成功')
        this.dialogVisible = false
        this.aiReviewResult = {}
      })
    },
  },
};
</script>