<template>
  <div class="review-container" v-loading="loading && aiAnalysisLoading" :element-loading-text="loading ? '数据获取中...' : 'AI分析中...'">
    <!-- 患者信息部分 -->
    <div class="patient-info">
      <h3>患者信息</h3>
      <el-form label-width="80px" inline style="margin-bottom: -18px;margin-top: 12px;">
        <el-form-item label="姓名:">
          {{ aiResult.name }}
        </el-form-item>
        <el-form-item label="性别:">
          {{ aiResult.sex !== 0 ? aiResult.sex == '1' ? '男' : '女' : '' }}
        </el-form-item>
        <el-form-item label="年龄:">
          {{ aiResult.age }}
        </el-form-item>
        <div style="height: 100px;overflow: auto;">
          <el-form-item label="患者病历:">{{ patientCase }}</el-form-item>
        </div>
      </el-form>
    </div>

    <div class="main-content">
      <!-- 左侧舌诊图片上传 -->
      <div class="upload-section">
        <h3>舌诊图片</h3>
        <img v-if="aiResult.imgUrl" class="uploaded-image" :src="aiResult.imgUrl" alt="">
        <br>
        <el-button v-if="aiResult.imgUrl" type="danger" @click="imgQualified">图片不合格</el-button>
      </div>

      <!-- 右侧对比结果 -->
      <div class="result-section">
        <h3>舌诊结果对比</h3>
        <div class="comparison-container">
          <!-- 复核结果 -->
          <div class="review-result">
            <!-- <el-table :data="quota" border stripe >
              <el-table-column prop="label" label="舌诊项目" width="100"></el-table-column>
              <el-table-column label="AI结果" width="100">
                <template slot-scope="scope">
                  {{ aiResult[scope.row.value] }}
                </template>
              </el-table-column>
              <el-table-column label="复核结果">
                <template slot-scope="scope">
                  <el-radio-group v-model="reviewResult[scope.row.value]">
                    <el-radio v-for="item in getObj(scope.row.value)" :key="item" :label="item" @click.native.prevent="handleRadioChange(scope.row.value, item)">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
            </el-table> -->

            <el-table
              :data="[aiResult, {}]"
              border>
              <el-table-column
                prop="createBy"
                label="结果来源"
                align="center"
                width="120">
                <template slot-scope="{row, $index}">
                  {{ $index === 0 ? 'AI分析' : '医生复核' }}
                </template>
              </el-table-column>
              <el-table-column
                prop="tongueColour"
                label="舌色">
                <template slot-scope="{row, $index}">
                  <span :style="{color: row.tongueColour === aiResult.tongueColour ? '':'red'}">{{row.tongueColour}}</span>
                  <el-radio-group v-model="reviewResult['tongueColour']" v-if="$index === 1">
                    <el-radio style="display: block;" v-for="item in getObj('tongueColour')" :key="item" :label="item">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
              <el-table-column
                prop="tongueShapes"
                label="舌形">
                <template slot-scope="{row, $index}">
                  <span :style="{color: row.tongueShapes === aiResult.tongueShapes ? '':'red'}">{{row.tongueShapes}}</span>
                  <el-radio-group v-model="reviewResult['tongueShapes']" v-if="$index === 1">
                    <el-radio style="display: block;" v-for="item in getObj('tongueShapes')" :key="item" :label="item">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
              <el-table-column
                prop="tongueFurqualitys"
                label="苔质">
                <template slot-scope="{row, $index}">
                  <span :style="{color: row.tongueFurqualitys === aiResult.tongueFurqualitys ? '':'red'}">{{row.tongueFurqualitys}}</span>
                  <el-radio-group v-model="reviewResult['tongueFurqualitys']" v-if="$index === 1">
                    <el-radio style="display: block;" v-for="item in getObj('tongueFurqualitys')" :key="item" :label="item">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
              <el-table-column
                prop="tonguefurColour"
                label="苔色">
                <template slot-scope="{row, $index}">
                  <span :style="{color: row.tonguefurColour === aiResult.tonguefurColour ? '':'red'}">{{row.tonguefurColour}}</span>
                  <el-radio-group v-model="reviewResult['tonguefurColour']" v-if="$index === 1">
                    <el-radio style="display: block;" v-for="item in getObj('tonguefurColour')" :key="item" :label="item">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
              <el-table-column
                prop="bodyFluid"
                label="津液">
                <template slot-scope="{row, $index}">
                  <span :style="{color: row.bodyFluid === aiResult.bodyFluid ? '':'red'}">{{row.bodyFluid}}</span>
                  <el-radio-group v-model="reviewResult['bodyFluid']" v-if="$index === 1">
                    <el-radio style="display: block;" v-for="item in getObj('bodyFluid')" :key="item" :label="item">
                      {{ item }}
                    </el-radio>
                  </el-radio-group>
                </template>
              </el-table-column>
            </el-table>

          </div>
        </div>

        <!-- 操作按钮 -->
        <div class="actions">
          <el-button @click="resetForm">重置</el-button>
          <el-button type="primary" @click="submitForm">
            提交复核结果
          </el-button>
          <!-- <el-button @click="DSAnalysis">
            AI再分析
          </el-button> -->
        </div>
      </div>
    </div>

    <!-- 注意事项 -->
    <!-- <div class="notice">
      <h4>注意：</h4>
      <ol>
        <li>提交结果可以修改</li>
        <li>图片标记不合格的，是否需要选择原因：图片不清晰、明暗不均等等</li>
      </ol>
    </div> -->


    <AiResutlDialog ref="AiResutlDialog"/>
  </div>
</template>

<script>
import {addTongueDiagnosisResult, getTongueAiDiagnosis, DSAnalysis} from '@/service/shezhen'
import {getPatientCase} from '@/service/referral'
import AiResutlDialog from './aiResult'
export default {
  name: 'Review',
  data() {
    return {
      loading: false,
      aiAnalysisLoading: false,
      patientCase: '',
      patientInfo: {},
      imageUrl: '',
      aiResult: {},
      reviewResult: {},
      quota: [{label: '舌色', value: 'tongueColour'}, {label: '舌形', value: 'tongueShapes'}, {label: '苔质', value: 'tongueFurqualitys'}, {label: '苔色', value: 'tonguefurColour'}, {label: '津液', value: 'bodyFluid'}],
      tongueColour: ['淡红舌', '淡白舌', '红舌', '绛舌', '青紫舌'],
      tongueShapes: ['老舌', '嫩舌', '胖大舌', '肿胀舌', '瘦薄舌', '点刺舌', '裂纹舌', '齿痕舌'],
      tongueFurqualitys: ['薄苔', '厚苔', '润苔', '燥苔', '腻苔', '腐苔', '剥（落）苔', '偏苔', '全苔'],
      tonguefurColour: ['白苔', '黄苔', '灰黑苔'],
      bodyFluid: ['润', '滑', '燥']
    }
  },
  components: {
    AiResutlDialog
  },
  computed: {
  },
  created() {
    this.getTongueAiDiagnosis()
  },
  methods: {
    getObj(str) {
      return this[str]
    },
    getTongueAiDiagnosis() {
      this.loading = true
      getTongueAiDiagnosis({}).then(res => {
        if (res) {
          this.aiResult = res
          this.reviewResult = JSON.parse(JSON.stringify(res))

          getPatientCase(res.patId).then(res2 => {
            this.patientCase = res2?.[0]?.richContent || '患者暂无病历'
          }).catch(err => {
            this.patientCase = '患者暂无病历'
          })
        } else {
          this.aiResult = {}
          this.$message.error('已全部复核完毕')
        }
      }).finally(() => {
        this.loading = false
      })
    },
    handleImageChange(file) {
      this.imageUrl = URL.createObjectURL(file.raw)
    },
    handleRadioChange(type, ele) {
      // if (this.reviewResult[type] == ele) {
      //   this.$set(this.reviewResult, type, '')
      // } else {
      //   this.$set(this.reviewResult, type, ele)
      // }
    },
    resetForm() {
      this.patientInfo = {}
      this.imageUrl = ''
      this.reviewResult = {
        tongueColour: '',
        tongueShapes: '',
        tongueFurqualitys: '',
        tonguefurColour: '',
        bodyFluid: ''
      }
    },
    submitForm() {
      addTongueDiagnosisResult({
        ...this.aiResult,
        tongueId: this.aiResult.id,
        tongueColour: this.reviewResult.tongueColour,
        tongueShapes: this.reviewResult.tongueShapes,
        tongueFurqualitys: this.reviewResult.tongueFurqualitys,
        tonguefurColour: this.reviewResult.tonguefurColour,
        bodyFluid: this.reviewResult.bodyFluid,
        imgFlag: 0,
        // createBy: 'AI'
      }).then(res => {
        this.$message.success('提交成功')
        this.resetForm()
        this.getTongueAiDiagnosis()
      })
    },
    imgQualified() {
      addTongueDiagnosisResult({
        ...this.aiResult,
        tongueId: this.aiResult.id,
        tongueColour: '',
        tongueShapes: '',
        tongueFurqualitys: '',
        tonguefurColour: '',
        bodyFluid: '',
        imgFlag: 1
      }).then(res => {
        this.resetForm()
        this.getTongueAiDiagnosis()
      })
    },
    DSAnalysis() {
      this.aiAnalysisLoading = true
      DSAnalysis(this.aiResult).then(res => {
        this.$refs.AiResutlDialog.show(JSON.parse(res.choices[0].message.content), this.aiResult)
      }).finally(() => {
        this.aiAnalysisLoading = false
      })
    }
  }
}
</script>

<style scoped lang="less">
.review-container {
  display: flex;
  flex-direction: column;
  background-color: transparent;
  /* padding: 20px; */
}

.patient-info {
  background-color: #fff;
  padding: 20px;
}

.main-content {
  flex: 1;
  display: flex;
  background-color: transparent;
  gap: 12px;
  margin-top: 12px;
  >div {
    padding: 20px;
    background-color: #fff;
  }
}

.upload-section {
  flex: 1;
  text-align: center;
  >h3 {
    text-align: left;
    margin-bottom: 16px;
  }
}
.result-section {
  flex: 2;
}

.uploaded-image {
  max-width: 100%;
  min-width: 300px;
  max-height: 60vh;
  object-fit: contain;
  background: #eee;
  padding: 12px;
  margin-bottom: 16px;
}

.comparison-container {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 24px;
}

.notice {
  margin-top: 20px;
  padding: 15px;
  background-color: #fdf6ec;
  border-radius: 4px;
}
.notice li {
  margin-left: 24px;
}

.actions {
  margin-top: 20px;
  text-align: right;
}

// .el-radio-group {
//   display: flex;
//   align-items: center;
//   flex-wrap: wrap;
//   gap: 10px;
// }
/deep/.el-table__cell {
  vertical-align: top;
}
.el-radio {
  height: 32px;
  line-height: 32px;
  margin: 0;
}
/deep/.el-radio:focus:not(.is-focus):not(:active):not(.is-disabled) .el-radio__inner {
  box-shadow: none;
}
/deep/.el-form-item__label {
  font-weight: 700;
}


</style>